INSERT INTO `products` VALUES (1,1,'iPhone 15 128GB','Chip A16 Bionic, camera 48MP, Dynamic Island, cổng USB-C.',19990000,25,5,'/products/1.jpg',1,'2026-04-13 22:08:35'),(2,1,'iPhone 15 Pro Max 256GB','Khung titan, chip A17 Pro, zoom quang 5x.',29990000,8,3,'/products/2.jpg',1,'2026-04-13 22:08:35'),(3,1,'Samsung Galaxy S24','Màn hình 6.2\" Dynamic AMOLED 2X, Galaxy AI.',18490000,18,5,'/products/3.jpg',1,'2026-04-13 22:08:35'),(4,1,'Samsung Galaxy A55 5G','Màn 6.6\" Super AMOLED 120Hz, pin 5000mAh.',9490000,35,8,'/products/4.jpg',1,'2026-04-13 22:08:35'),(5,1,'Xiaomi Redmi Note 13','Pin 5000mAh, sạc nhanh 33W, camera 108MP.',4890000,40,10,'/products/5.jpg',1,'2026-04-13 22:08:35'),(6,1,'OPPO Reno11 F 5G','Thiết kế mỏng nhẹ, camera chân dung 64MP.',8490000,22,5,'/products/6.jpg',1,'2026-04-13 22:08:35'),(7,1,'Google Pixel 8a','Chip Tensor G3, camera AI, 7 năm cập nhật.',11990000,6,3,'/products/7.jpg',1,'2026-04-13 22:08:35'),(8,2,'MacBook Air M2 13\"','Chip Apple M2, RAM 8GB, SSD 256GB, pin 18 giờ.',24990000,10,3,'/products/8.jpg',1,'2026-04-13 22:08:35'),(9,2,'MacBook Pro M3 14\"','Chip M3, RAM 16GB, màn Liquid Retina XDR.',39990000,5,2,'/products/9.jpg',1,'2026-04-13 22:08:35'),(10,2,'Dell Inspiron 15 3530','Laptop văn phòng, học tập Core i5 Gen 13, RAM 16GB, SSD 512GB (card tích hợp).',15990000,12,4,'/products/10.jpg',1,'2026-04-13 22:08:35'),(11,2,'Asus TUF Gaming F15','Laptop gaming Core i7, card RTX 4050, màn 144Hz – chơi game, đồ họa.',22990000,4,3,'/products/11.jpg',1,'2026-04-13 22:08:35'),(12,2,'Lenovo IdeaPad Slim 5','Laptop mỏng nhẹ văn phòng Ryzen 7 7730U, RAM 16GB, màn 2.2K (card tích hợp).',17490000,9,3,'/products/12.jpg',1,'2026-04-13 22:08:35'),(13,2,'HP Victus 16','Laptop gaming Core i5, card RTX 3050, màn 144Hz 16.1\" – chơi game mượt.',19990000,7,3,'/products/13.jpg',1,'2026-04-13 22:08:35'),(14,2,'Acer Aspire 7','Laptop gaming giá rẻ Ryzen 5, card GTX 1650 – chơi game phổ thông.',14990000,3,3,'/products/14.jpg',1,'2026-04-13 22:08:35'),(15,3,'iPa